import networkx as nx
G = nx.Graph()
for i in range(25):
    for j in range(i+1, 25):
        if len(list(G.neighbors(i))) < 6 and len(list(G.neighbors(j))) < 6 and nx.shortest_path_length(G, source=i, target=j, weight=None, method="unweighted") > 5:
            G.add_edge(i, j)
if min(degree for node, degree in G.degree()) >= 5 and max(degree for node, degree in G.degree()) <= 6 and nx.girth(G) >= 6:
    print("SATISFIABLE")
    print(list(G.edges))
else:
    print("UNSATISFIABLE")
